import json, sys
data = json.load(sys.stdin)
result = json.loads(data['result'])
exps = result['data']['experiments']

# Find all v2 eval experiments that are DONE with CAR metrics
# Also find all v2 training experiments
cells = {
    'Cell 1 (Full OCC BN)': [],
    'Cell 2 (Full OCC LN)': [],
    'Cell 3 (Detach BN)': [],
    'Cell 4 (Detach LN)': [],
    'Vanilla': []
}

for eid, e in exps.items():
    if e.get('status') != 'DONE' or e.get('conclusion') not in ('success', 'negative'):
        continue
    metrics = e.get('metrics', {})
    car = metrics.get('car') or metrics.get('CAR')
    if car is None:
        continue

    # Classify by cell
    eid_lower = eid.lower()
    if 'vanilla' in eid_lower and 'object' not in eid_lower:
        cells['Vanilla'].append((eid, car, 'v2' if 'v2' in eid_lower else 'v1'))
    elif 'full_occ_ln' in eid_lower or 'full_occ_ln_v2' in eid_lower:
        if 'eval' in eid_lower:
            v = 'v2' if 'v2' in eid_lower else 'v1'
            cells['Cell 2 (Full OCC LN)'].append((eid, car, v))
    elif 'full_occ' in eid_lower and 'ln' not in eid_lower and 'retrain' not in eid_lower:
        if 'eval' in eid_lower:
            v = 'v2' if 'v2' in eid_lower else 'v1'
            cells['Cell 1 (Full OCC BN)'].append((eid, car, v))
    elif 'detach_ln' in eid_lower or 'detach_ln_v2' in eid_lower:
        if 'eval' in eid_lower:
            v = 'v2' if 'v2' in eid_lower else 'v1'
            cells['Cell 4 (Detach LN)'].append((eid, car, v))
    elif 'detach' in eid_lower and 'ln' not in eid_lower:
        if 'eval' in eid_lower or 'ablation_occ_detach' in eid_lower:
            v = 'v2' if 'v2' in eid_lower else 'v1'
            cells['Cell 3 (Detach BN)'].append((eid, car, v))

# Also check for non-eval experiments with metrics (some have metrics directly)
for eid, e in exps.items():
    if e.get('status') != 'DONE' or e.get('conclusion') not in ('success', 'negative'):
        continue
    metrics = e.get('metrics', {})
    car = metrics.get('car') or metrics.get('CAR')
    if car is None:
        continue
    eid_lower = eid.lower()
    # Check vanilla non-eval
    if 'vanilla' in eid_lower and 'object' not in eid_lower and 'eval' not in eid_lower:
        # Already captured above
        pass

for cell, data in cells.items():
    print(f'\n{cell}:')
    v2_data = [(eid, car) for eid, car, v in data if v == 'v2']
    v1_data = [(eid, car) for eid, car, v in data if v == 'v1']
    print(f'  v2 confirmed: {len(v2_data)}')
    for eid, car in v2_data:
        print(f'    {eid}: CAR={car}')
    if v1_data:
        print(f'  v1 (not used): {len(v1_data)}')
        for eid, car in v1_data:
            print(f'    {eid}: CAR={car}')
